// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }

    function testFuzz_property(address proposedOwner) public {
        // Only the admin (the deployer == address(this)) may call setOwner.
        // Restrict to admissible domain: proposals different from the admin itself.
        vm.assume(proposedOwner != address(this));

        vm.prank(address(this));
        c.setOwner(proposedOwner);

        assertTrue(c.owner() == proposedOwner);
    }
}
